   <a class="skip-link" href="#main-content">Skip to main content</a>
   <div id="app"></div>

   <script>
     const appRoot = document.getElementById("app");

     function PageShell(content) {
       return `
         <main id="main-content" tabindex="-1">
           <section class="page-shell" aria-labelledby="page-title">
             ${content}
           </section>
         </main>
       `;
     }

     function RadioField() {
       return `
         <div class="form-field">
           <fieldset id="notification-group" aria-describedby="notification-help">
             <legend>
               How do you prefer to receive notifications?
               <span class="required-indicator" aria-hidden="true">*</span>
             </legend>
             <p class="field-help" id="notification-help">Choose one option before submitting the form.</p>
             <p class="field-error" id="notification-error" role="alert" aria-atomic="true" hidden></p>

             <div class="radio-options">
               <label class="radio-option" for="notification-email">
                 <input id="notification-email" name="notificationPreference" type="radio" value="Email" required>
                 <span class="radio-label">Email</span>
               </label>

               <label class="radio-option" for="notification-sms">
                 <input id="notification-sms" name="notificationPreference" type="radio" value="SMS" required>
                 <span class="radio-label">SMS</span>
               </label>

               <label class="radio-option" for="notification-push">
                 <input id="notification-push" name="notificationPreference" type="radio" value="Push Notifications" required>
                 <span class="radio-label">Push Notifications</span>
               </label>
             </div>
           </fieldset>
         </div>
       `;
     }

     function App() {
       return PageShell(`
         <p class="eyebrow">Preferences</p>
         <h1 id="page-title">Notification settings</h1>
         <p class="intro">Tell us how you would like to hear from us so we can use your preferred notification channel.</p>

         <form id="notification-form" novalidate>
           <p class="required-note"><span class="required-indicator" aria-hidden="true">*</span> Required field</p>
           ${RadioField()}
           <button type="submit">Save notification preference</button>
           <p id="form-status" class="status-message" role="status" aria-live="polite" aria-atomic="true"></p>
         </form>
       `);
     }

     function render() {
       appRoot.innerHTML = App();
     }

     function setupForm() {
       const form = document.getElementById("notification-form");
       const fieldset = document.getElementById("notification-group");
       const error = document.getElementById("notification-error");
       const status = document.getElementById("form-status");
       const radios = Array.from(form.elements.namedItem("notificationPreference"));

       function showError(message) {
         error.textContent = message;
         error.hidden = false;
         fieldset.setAttribute("aria-describedby", "notification-help notification-error");
         radios.forEach((radio) => radio.setAttribute("aria-invalid", "true"));
       }

       function clearError() {
         error.textContent = "";
         error.hidden = true;
         fieldset.setAttribute("aria-describedby", "notification-help");
         radios.forEach((radio) => radio.removeAttribute("aria-invalid"));
       }

       radios.forEach((radio) => {
         radio.addEventListener("change", () => {
           clearError();
           status.textContent = "";
         });
       });

       clearError();

       form.addEventListener("submit", (event) => {
         const selected = radios.find((radio) => radio.checked);

         if (!selected) {
           event.preventDefault();
           showError("Error: Select how you prefer to receive notifications.");
           status.textContent = "";
           radios[0].focus();
           return;
         }

         event.preventDefault();
         clearError();
         status.textContent = `Preference saved: ${selected.value}.`;
       });
     }

     render();
     setupForm();
   </script>
 </body>
